package claudecode

import (
	"path/filepath"
	"runtime"
	"testing"

	"github.com/go-go-golems/go-minitrace/pkg/adapters"
	"github.com/go-go-golems/go-minitrace/pkg/minitrace"
)

const (
	fixtureParentID = "11111111-1111-4111-8111-111111111111"
	fixtureStubID   = "22222222-2222-4222-8222-222222222222"
)

// fixtureProjectDir is the synthetic project generated by the
// CLAUDE-CODE-NORMALIZE-2026-11-24 ticket script.
func fixtureProjectDir(t *testing.T) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatalf("locating test file")
	}
	return filepath.Join(filepath.Dir(file), "..", "..", "..", "testdata", "claude-code", "projects", "-tmp-demo")
}

func convertFixtureParent(t *testing.T) *minitrace.Session {
	t.Helper()
	path := filepath.Join(fixtureProjectDir(t), fixtureParentID+".jsonl")
	session, err := ConvertLocator(adapters.SessionLocator{ID: fixtureParentID, FormatHint: "jsonl-v2", SourcePath: path})
	if err != nil {
		t.Fatalf("ConvertLocator: %v", err)
	}
	return session
}

func toolCallByID(t *testing.T, session *minitrace.Session, id string) minitrace.ToolCall {
	t.Helper()
	for _, toolCall := range session.ToolCalls {
		if toolCall.ID == id {
			return toolCall
		}
	}
	t.Fatalf("tool call %s not found", id)
	return minitrace.ToolCall{}
}

func eventsOfKind(session *minitrace.Session, kind string) []minitrace.Event {
	ret := []minitrace.Event{}
	for _, event := range session.Events {
		if event.Kind == kind {
			ret = append(ret, event)
		}
	}
	return ret
}

func TestConvertRecordsExtractsContextLoads(t *testing.T) {
	session := convertFixtureParent(t)
	if len(session.ContextLoads) != 5 {
		t.Fatalf("context loads = %d, want 5: %+v", len(session.ContextLoads), session.ContextLoads)
	}
	type want struct {
		kind, path, name, fileType string
		turnIndex                  int
		toolCallID                 string
	}
	wants := []want{
		{minitrace.ContextLoadInstructions, "/tmp/demo/CLAUDE.md", "CLAUDE.md", "Project", 0, ""},
		{minitrace.ContextLoadInstructions, "/tmp/home/.claude/projects/-tmp-demo/memory/MEMORY.md", "MEMORY.md", "AutoMem", 0, ""},
		{minitrace.ContextLoadNestedMemory, "/tmp/demo/src/CLAUDE.md", "CLAUDE.md", "Project", 2, "toolu_bash1"},
		{minitrace.ContextLoadNestedMemory, "/tmp/demo/.claude/rules/style.md", "style.md", "Project", 2, "toolu_bash1"},
		{minitrace.ContextLoadInvokedSkill, "userSettings:diary", "diary", "", 4, ""},
	}
	for i, w := range wants {
		load := session.ContextLoads[i]
		if load.Kind != w.kind || load.Path != w.path || load.Name != w.name || load.FileType != w.fileType {
			t.Fatalf("load %d = %+v, want %+v", i, load, w)
		}
		if load.TurnIndex == nil || *load.TurnIndex != w.turnIndex {
			t.Fatalf("load %d turn_index = %v, want %d", i, load.TurnIndex, w.turnIndex)
		}
		gotToolCall := ""
		if load.ToolCallID != nil {
			gotToolCall = *load.ToolCallID
		}
		if gotToolCall != w.toolCallID {
			t.Fatalf("load %d tool_call_id = %q, want %q", i, gotToolCall, w.toolCallID)
		}
		if load.AttachmentID == nil || load.ContentSHA256 == "" || load.ContentBytes == 0 || load.ContentChars == 0 {
			t.Fatalf("load %d missing attachment/content facts: %+v", i, load)
		}
	}
	if session.ContextLoads[0].ContentSHA256 != session.ContextLoads[2].ContentSHA256 {
		t.Fatalf("identical CLAUDE.md content should hash identically")
	}
	if session.ContextLoads[2].DiffersFromDisk == nil || *session.ContextLoads[2].DiffersFromDisk {
		t.Fatalf("expected differs_from_disk=false, got %v", session.ContextLoads[2].DiffersFromDisk)
	}
}

func TestConvertRecordsClassifiesToolOutcomes(t *testing.T) {
	session := convertFixtureParent(t)
	blocked := toolCallByID(t, session, "toolu_bash1")
	if blocked.Output.Reason != minitrace.ToolOutcomeReasonHookBlocked || blocked.Output.OutcomeStatus() != minitrace.ToolOutcomeFailed {
		t.Fatalf("hook-blocked call: reason=%q status=%q", blocked.Output.Reason, blocked.Output.OutcomeStatus())
	}
	denied := toolCallByID(t, session, "toolu_bash2")
	if denied.Output.Reason != minitrace.ToolOutcomeReasonClassifierDenied || !denied.Output.Failed() {
		t.Fatalf("classifier-denied call: reason=%q success=%v", denied.Output.Reason, denied.Output.Success)
	}
	grep := toolCallByID(t, session, "toolu_grep")
	if grep.Output.Reason != "" || !grep.Output.Succeeded() {
		t.Fatalf("grep output quoting a denial phrase must stay a plain success: reason=%q success=%v", grep.Output.Reason, grep.Output.Success)
	}
}

func TestClassifyClaudeToolOutcomePrefixes(t *testing.T) {
	cases := []struct {
		text    string
		isError bool
		reason  string
	}{
		{"Permission to use Bash with command rm -rf x has been denied.", true, minitrace.ToolOutcomeReasonPermissionDenied},
		{"The server-side auto mode classifier gave no verdict for Bash: ...", true, minitrace.ToolOutcomeReasonClassifierNoVerdict},
		{"The user doesn't want to proceed with this tool use. The tool use was rejected", true, minitrace.ToolOutcomeReasonUserRejected},
		{"The user doesn't want to take this action right now. STOP", true, minitrace.ToolOutcomeReasonUserRejected},
		{"<tool_use_error>File has not been read yet.</tool_use_error>", true, minitrace.ToolOutcomeReasonToolUseError},
		{"This agent is isolated in the worktree /tmp/wt, but this command is too complex", true, minitrace.ToolOutcomeReasonHarnessBlocked},
		{"Permission to use the API is documented in README", false, ""},
		{"Exit code 1\nboom", true, ""},
	}
	for _, c := range cases {
		toolCall := minitrace.ToolCall{}
		toolCall.Output.SetSuccess(!c.isError)
		classifyClaudeToolOutcome(&toolCall, c.text, c.isError)
		if toolCall.Output.Reason != c.reason {
			t.Fatalf("%q: reason = %q, want %q", c.text, toolCall.Output.Reason, c.reason)
		}
	}
}

func TestConvertRecordsMapsHookAndMarkerEvents(t *testing.T) {
	session := convertFixtureParent(t)
	hooks := eventsOfKind(session, "hook")
	if len(hooks) != 2 {
		t.Fatalf("hook events = %d, want 2", len(hooks))
	}
	pre := hooks[0]
	metadata := pre.FrameworkMetadata.(map[string]any)
	if pre.ToolCallID == nil || *pre.ToolCallID != "toolu_bash1" || pre.Title != "PreToolUse:Bash" || metadata["permission_decision"] != "deny" || metadata["hook_type"] != "hook_success" || pre.AttachmentID == nil {
		t.Fatalf("unexpected PreToolUse hook event: %+v metadata=%+v", pre, metadata)
	}
	stop := hooks[1]
	stopMetadata := stop.FrameworkMetadata.(map[string]any)
	if stop.ToolCallID == nil || *stop.ToolCallID != "toolu_grep" || stopMetadata["hook_type"] != "stop_hook_summary" {
		t.Fatalf("unexpected stop hook event: %+v metadata=%+v", stop, stopMetadata)
	}

	compactions := eventsOfKind(session, "compaction")
	if len(compactions) != 1 || compactions[0].TurnIndex == nil || *compactions[0].TurnIndex != 3 {
		t.Fatalf("compaction events = %+v", compactions)
	}
	compactMetadata := compactions[0].FrameworkMetadata.(map[string]any)
	if compactMetadata["trigger"] != "auto" || compactMetadata["pre_tokens"] != 400000 || compactMetadata["post_tokens"] != 50000 {
		t.Fatalf("compaction metadata = %+v", compactMetadata)
	}
	if session.Turns[3].Role != "user" || session.Turns[3].Content != "This session is being continued from a previous conversation." {
		t.Fatalf("compaction turn_index should name the first turn after the boundary, got %+v", session.Turns[3])
	}

	durations := eventsOfKind(session, "turn_duration")
	if len(durations) != 2 || durations[0].TurnIndex == nil || *durations[0].TurnIndex != 2 || durations[1].TurnIndex == nil || *durations[1].TurnIndex != 6 {
		t.Fatalf("turn_duration events = %+v", durations)
	}
	for _, turn := range session.Turns {
		if turn.Role == "system" {
			t.Fatalf("marker system records must not become turns: %+v", turn)
		}
	}
	if session.Metrics.CompactionCount == nil || *session.Metrics.CompactionCount != 1 {
		t.Fatalf("compaction_count = %v", session.Metrics.CompactionCount)
	}
	if session.Metrics.TotalTurnDurationMS == nil || *session.Metrics.TotalTurnDurationMS != 151000 {
		t.Fatalf("total_turn_duration_ms = %v", session.Metrics.TotalTurnDurationMS)
	}
}

func TestHookBlockingErrorMarksPreToolUseCall(t *testing.T) {
	records := []map[string]any{
		{"type": "assistant", "uuid": "a1", "timestamp": "2026-11-20T10:00:00Z", "message": map[string]any{"role": "assistant", "content": []any{
			map[string]any{"type": "tool_use", "id": "toolu_x", "name": "Bash", "input": map[string]any{"command": "rm -rf build"}},
		}}},
		{"type": "attachment", "uuid": "h1", "parentUuid": "a1", "timestamp": "2026-11-20T10:00:01Z", "attachment": map[string]any{
			"type": "hook_blocking_error", "hookName": "PreToolUse:Bash", "hookEvent": "PreToolUse", "toolUseID": "toolu_x",
			"blockingError": map[string]any{"blockingError": "rm -rf is not allowed", "command": "guard.sh"},
		}},
		{"type": "user", "uuid": "u1", "parentUuid": "h1", "timestamp": "2026-11-20T10:00:02Z", "message": map[string]any{"role": "user", "content": []any{
			map[string]any{"type": "tool_result", "tool_use_id": "toolu_x", "content": "rm -rf is not allowed", "is_error": false},
		}}},
	}
	session, err := ConvertRecords(records, "s1", "")
	if err != nil {
		t.Fatalf("ConvertRecords: %v", err)
	}
	toolCall := toolCallByID(t, session, "toolu_x")
	if toolCall.Output.Reason != minitrace.ToolOutcomeReasonHookBlocked || !toolCall.Output.Failed() {
		t.Fatalf("blocking PreToolUse hook: reason=%q success=%v", toolCall.Output.Reason, toolCall.Output.Success)
	}
	hooks := eventsOfKind(session, "hook")
	if len(hooks) != 1 || hooks[0].Severity != "error" || hooks[0].Text != "rm -rf is not allowed" {
		t.Fatalf("hook events = %+v", hooks)
	}
}

func TestConvertRecordsLinksSpawnedAgentsFromToolResults(t *testing.T) {
	session := convertFixtureParent(t)
	linked := toolCallByID(t, session, "toolu_agent1")
	if linked.SpawnedAgent == nil || linked.SpawnedAgent.SubSessionID == nil || *linked.SpawnedAgent.SubSessionID != "a1111111111111111" {
		t.Fatalf("agentId from toolUseResult should link the spawn: %+v", linked.SpawnedAgent)
	}
	unlinked := toolCallByID(t, session, "toolu_agent2")
	if unlinked.SpawnedAgent == nil || unlinked.SpawnedAgent.SubSessionID != nil {
		t.Fatalf("spawn without agentId in its result should wait for meta linking: %+v", unlinked.SpawnedAgent)
	}
}

func TestConvertRecordsLinksForkSpawnEchoToItself(t *testing.T) {
	records := []map[string]any{
		{"type": "fork-context-ref", "agentId": "afork", "parentSessionId": "parent-1"},
		{"type": "assistant", "uuid": "a1", "isSidechain": true, "agentId": "afork", "sessionId": "parent-1", "timestamp": "2026-11-20T10:00:00Z", "message": map[string]any{"role": "assistant", "content": []any{
			map[string]any{"type": "tool_use", "id": "toolu_fork", "name": "Agent", "input": map[string]any{"prompt": "fork"}},
		}}},
		{"type": "user", "uuid": "u1", "isSidechain": true, "agentId": "afork", "sessionId": "parent-1", "timestamp": "2026-11-20T10:00:01Z", "message": map[string]any{"role": "user", "content": []any{
			map[string]any{"type": "tool_result", "tool_use_id": "toolu_fork", "content": "Fork started — that fork is you."},
		}}},
	}
	session, err := ConvertTranscript(records, "fallback", "")
	if err != nil {
		t.Fatalf("ConvertTranscript: %v", err)
	}
	if session.ID != "afork" || session.Coordination.PredecessorSession == nil || *session.Coordination.PredecessorSession != "parent-1" {
		t.Fatalf("fork transcript should convert as subagent of parent-1: id=%s predecessor=%v", session.ID, session.Coordination.PredecessorSession)
	}
	echo := toolCallByID(t, session, "toolu_fork")
	if echo.SpawnedAgent == nil || echo.SpawnedAgent.SubSessionID == nil || *echo.SpawnedAgent.SubSessionID != "afork" {
		t.Fatalf("fork spawn echo should link to the fork itself: %+v", echo.SpawnedAgent)
	}
	if echo.FrameworkMetadata.(map[string]any)["fork_spawn_echo"] != true {
		t.Fatalf("fork spawn echo should be marked: %+v", echo.FrameworkMetadata)
	}
}
